<script setup>
import {ref,reactive,computed,watch,onMounted,onBeforeUnmount} from 'vue'
import ScreenMap from './ScreenMap.vue'
import ScreenChart from './ScreenChart.vue'
import {rivers,layers,exactValue,timelineDates,balanceTerms,defaultReplayDay} from './dashboard.mjs'
import {preferredHistoricalInput} from './workflow.mjs'
const props=defineProps({boot:Object,tasks:Array})
const emit=defineEmits(['navigate','result','station'])
const mode=ref('model'),taskId=ref(''),task=ref(null),monitor=ref(null),day=ref(''),stationId=ref('SLC'),variable=ref('basin'),frame=ref(null),snow=ref(null),loading=ref(false),mapLoading=ref(false),error=ref(''),mapError=ref(''),playing=ref(false),speed=ref(1),expanded=ref(false),dark=ref(localStorage.getItem('selinco:screen-theme')==='dark'),host=ref(),clock=ref(''),feature=ref(null),inputId=ref('')
const show=reactive({ice:true,rivers:true,terrain:true,stations:true,control:false,names:true})
let playTimer,clockTimer,taskSequence=0,mapSequence=0,disposed=false
const number=(v,n=2)=>v==null||!Number.isFinite(Number(v))?'—':(Math.abs(Number(v))<.5*10**-n?0:Number(v)).toLocaleString('zh-CN',{maximumFractionDigits:n})
const available=computed(()=>props.tasks.filter(t=>t.status==='succeeded'&&!t.trashed&&['simulation','trial','continuation','calibration'].includes(t.kind)))
const result=computed(()=>mode.value==='model'?task.value?.result:null)
const dates=computed(()=>timelineDates(mode.value,monitor.value,result.value))
const index=computed(()=>Math.max(0,dates.value.indexOf(day.value)))
const current=computed(()=>result.value?.daily.find(r=>r.date.slice(0,10)===day.value))
const main=computed(()=>monitor.value?.stations.find(s=>s.id==='SLC'))
const stations=computed(()=>monitor.value?.stations||[])
const selected=computed(()=>stations.value.find(s=>s.id===stationId.value))
const observedLevel=computed(()=>mode.value==='model'?current.value?.observedLevel:exactValue(main.value,day.value))
const duja=computed(()=>mode.value==='model'?current.value?.duja:exactValue(stations.value.find(s=>s.id==='DUJA'),day.value))
const selectedValue=computed(()=>{if(mode.value==='model'&&stationId.value==='SLC')return current.value?.observedLevel??null;if(mode.value==='model'&&stationId.value==='DUJA')return current.value?.observedFlow??null;return exactValue(selected.value,day.value)})
const selectedUnit=computed(()=>selected.value?.variable==='level'?'m':selected.value?.variable==='flow'?'m³/s':'mm/d')
const selectedRows=computed(()=>{
 const rows=selected.value?.daily||[]
 if(mode.value==='model'&&['SLC','DUJA'].includes(stationId.value))return(result.value?.daily||[]).map(r=>({date:r.date,value:r[stationId.value==='SLC'?'observedLevel':'observedFlow'],sim:r[stationId.value==='SLC'?'lakeLevel':'duja']}))
 const i=rows.findIndex(r=>r.date>=day.value);return rows.slice(Math.max(0,(i<0?rows.length:i)-20),Math.min(rows.length,(i<0?rows.length:i)+20))
})
const lakeRows=computed(()=>result.value?.daily||main.value?.daily||[])
const flowRows=computed(()=>result.value?.daily||stations.value.find(s=>s.id==='DUJA')?.daily||[])
const flux=computed(()=>balanceTerms(current.value))
const volumeScale=computed(()=>Math.max(1,...flux.value.map(f=>Math.abs(f.value||0))))
const basinStats=computed(()=>rivers.map(r=>({...r,spatial:props.boot.spatial?.basins.find(b=>b.id===r.id),flow:current.value?.[r.id]})))
const selectedInput=computed(()=>props.boot.inputs.find(i=>i.id===(result.value?.inputId||inputId.value)))
const frameCompatible=computed(()=>frame.value?.day===day.value&&frame.value?.inputId===(result.value?.inputId||inputId.value)&&frame.value?.variable===variable.value)
const mapFrame=computed(()=>frameCompatible.value?frame.value:null)
const mapSnow=computed(()=>snow.value?.day===day.value&&snow.value?.taskId===taskId.value?snow.value:null)
const lakeDelta=computed(()=>{const a=current.value?.lakeLevel,b=result.value?.daily[index.value-1]?.lakeLevel;return a!=null&&b!=null?a-b:null})
const footprint=computed(()=>{const values=props.boot.inputs.filter(i=>i.compatible!==false);return values.map(i=>i.manifest.hours).reduce((a,b)=>Math.max(a,b),0)})
async function get(path){const r=await fetch('/api/model/'+path);const d=await r.json();if(!r.ok)throw Error(d.error||'读取失败');return d}
function stop(){playing.value=false;clearInterval(playTimer)}
function setDay(value){stop();if(dates.value.includes(value))day.value=value}
function move(n){const next=index.value+n;if(next<0||next>=dates.value.length){stop();return}day.value=dates.value[next]}
function play(){if(playing.value){stop();return}if(index.value>=dates.value.length-1)day.value=dates.value[0];playing.value=true;playTimer=setInterval(()=>{if(!mapLoading.value)move(1)},Math.max(650,1800/speed.value))}
async function selectTask(){const token=++taskSequence;stop();task.value=null;frame.value=null;snow.value=null;loading.value=true;error.value='';try{if(taskId.value){const d=await get('tasks/'+taskId.value);if(disposed||token!==taskSequence)return;if(!d.result?.daily)throw Error('该任务没有历史过程');if(d.result.spatialVersion!==props.boot.spatial?.version)throw Error('所选成果空间版本与当前地图不同');task.value=d;inputId.value=d.result.inputId}day.value=defaultReplayDay(dates.value,result.value)}catch(e){if(token===taskSequence)error.value=e.message}finally{if(token===taskSequence)loading.value=false}}
async function refreshMap(){const token=++mapSequence;frame.value=null;snow.value=null;mapError.value='';mapLoading.value=false;if(!day.value||variable.value==='basin')return;const id=result.value?.inputId||inputId.value;if(variable.value!=='snow'&&!id){mapError.value='请选择真实气象输入';return}if(variable.value==='snow'&&!result.value){mapError.value='雪水当量需要已完成的模型成果；此处不将冰川边界当作积雪观测。';return}mapLoading.value=true;try{const q=new URLSearchParams(variable.value==='snow'?{taskId:taskId.value,day:day.value}:{inputId:id,day:day.value,variable:variable.value});const d=await get((variable.value==='snow'?'snow-frame?':'map-frame?')+q);if(disposed||token!==mapSequence)return;if(variable.value==='snow')snow.value=d;else frame.value=d;if(!d.complete)mapError.value=d.message}catch(e){if(token===mapSequence)mapError.value=e.message}finally{if(token===mapSequence)mapLoading.value=false}}
function modeChanged(){stop();frame.value=null;snow.value=null;if(mode.value==='observation')inputId.value=preferredHistoricalInput(props.boot.inputs)?.id||'';day.value=defaultReplayDay(dates.value,result.value)}
async function fullscreen(){if(document.fullscreenElement){await document.exitFullscreen();return}expanded.value=true;try{await host.value.requestFullscreen()}catch{/* Immersive layout remains available if browser policy blocks native fullscreen. */}}
function closeScreen(){if(document.fullscreenElement)document.exitFullscreen();expanded.value=false}
function syncFullscreen(){if(!document.fullscreenElement)expanded.value=false}
function keys(e){if(e.key==='Escape')expanded.value=false}
function openStation(){emit('station',stationId.value,day.value)}
watch([day,variable,inputId,()=>result.value?.inputId],refreshMap)
watch(dark,v=>localStorage.setItem('selinco:screen-theme',v?'dark':'light'))
watch(speed,()=>{if(playing.value){stop();play()}})
watch(available,rows=>{if(taskId.value&&!rows.some(r=>r.id===taskId.value)){taskId.value='';task.value=null;mode.value='observation';modeChanged()}})
onMounted(async()=>{document.addEventListener('fullscreenchange',syncFullscreen);document.addEventListener('keydown',keys);const tick=()=>clock.value=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date());tick();clockTimer=setInterval(tick,1000);loading.value=true;try{monitor.value=await get('dashboard');const sources=props.boot.inputs.filter(i=>i.compatible!==false);inputId.value=preferredHistoricalInput(sources)?.id||'';if(available.value.length){taskId.value=(available.value.find(t=>t.favorite&&t.collection==='完整历史')||available.value[0]).id;await selectTask()}else{mode.value='observation';day.value=dates.value.at(-1)||''}}catch(e){error.value=e.message}finally{loading.value=false}})
onBeforeUnmount(()=>{disposed=true;stop();clearInterval(clockTimer);document.removeEventListener('fullscreenchange',syncFullscreen);document.removeEventListener('keydown',keys)})
</script>
<template>
 <section ref="host" class="lake-screen" :class="{'screen-dark':dark,'screen-expanded':expanded}" aria-label="色林错湖情监视大屏">
  <div class="screen-masthead"><div class="screen-wordmark"><span>◈</span><div><h2>色林错预警预报平台</h2><p>SELINCO · LAKE & BASIN OBSERVATORY</p></div></div><div class="screen-state"><i></i><b>{{mode==='model'?'历史模拟回放':'历史监测回放'}}</b><small>北京时间 {{clock}}</small></div><div class="screen-header-actions"><button @click="emit('navigate','simulation')">业务工作台 ↗</button><button @click="dark=!dark">{{dark?'☀ 日常浅色':'◐ 汇报深色'}}</button><button v-if="!expanded" @click="fullscreen">⛶ 全屏展示</button><button v-else @click="closeScreen">退出全屏 Esc</button></div></div>
  <div class="screen-context"><div class="screen-modes"><button :class="{on:mode==='model'}" :disabled="!available.length" @click="mode='model';modeChanged()">模型成果</button><button :class="{on:mode==='observation'}" @click="mode='observation';modeChanged()">站点监测</button></div><label v-if="mode==='model'">计算成果<select v-model="taskId" @change="selectTask"><option v-for="t in available" :key="t.id" :value="t.id">{{t.name||t.id}}</option></select></label><label v-else>气象输入<select v-model="inputId"><option value="">无气象叠加</option><option v-for="i in boot.inputs.filter(i=>i.compatible!==false)" :key="i.id" :value="i.id">{{i.name}}</option></select></label><span class="screen-context-time">回放日期 <b>{{day||'—'}}</b></span><span class="screen-context-note">{{mode==='model'?'模拟值与实测分别标识 · 参数未率定时只作过程检查':'各站按所选日期展示 · 缺测不沿用最近值'}}</span><button @click="mode==='model'?emit('result',taskId):emit('navigate','monitor')">{{mode==='model'?'查看完整成果 ↗':'查询原始资料 ↗'}}</button></div>
  <div v-if="error" role="alert" class="screen-alert">{{error}}</div>
  <div class="screen-kpis"><article class="primary-kpi"><span>{{mode==='model'?'模拟日湖位':'主站日湖位'}} <em>m</em></span><b>{{number(mode==='model'?current?.lakeLevel:observedLevel,3)}}</b><small>{{day||'未选日期'}} <i>{{mode==='model'?'模型计算':'整编实测'}}</i></small></article><article><span>主站匹配实测 <em>m</em></span><b>{{number(observedLevel,3)}}</b><small>{{observedLevel==null?'该日无可靠观测':'可靠日值 · 四岸不混合'}}</small></article><article><span>{{mode==='model'?'总入湖流量':'杜加日流量'}} <em>m³/s</em></span><b>{{number(mode==='model'?current?.total:duja,1)}}</b><small>{{mode==='model'?'四河 + 湖周来水 · 模拟':'内部断面 · 实测'}}</small></article><article><span>湖位日变化 <em>m/d</em></span><b>{{lakeDelta>=.0005?'+':''}}{{number(lakeDelta,3)}}</b><small>{{mode==='model'?'连续两日模拟湖位差':'需模型连续过程'}}</small></article><article><span>湖面定面积 <em>km²</em></span><b>{{number(boot.spatial?.lakeAreaKm2,1)}}</b><small>核验湖泊边界 · 首版固定</small></article><article><span>冰川范围 <em>km²</em></span><b>{{number(boot.spatial?.glacierAreaKm2,2)}}</b><small>{{boot.spatial?.glacierCount}} 个要素 · 固定范围</small></article></div>
  <div class="screen-main-grid">
   <aside class="screen-left">
    <section class="screen-card layer-card"><div class="screen-card-title"><h3>监视要素</h3><span>LAYERS</span></div><div class="screen-layer-buttons"><button v-for="l in layers" :key="l.id" :class="{on:variable===l.id}" @click="variable=l.id">{{l.label}}</button></div><div class="screen-switches"><label><input type="checkbox" v-model="show.terrain">地形</label><label><input type="checkbox" v-model="show.rivers">河网</label><label><input type="checkbox" v-model="show.ice">冰川</label><label><input type="checkbox" v-model="show.stations">测站</label><label><input type="checkbox" v-model="show.control">杜加控制区</label><label><input type="checkbox" v-model="show.names">分区标注</label></div><div class="screen-layer-value"><span>{{layers.find(l=>l.id===variable)?.label}} · {{variable==='snow'?'陆面面积加权':variable==='basin'?'控制域面积':'全控制域面积加权'}}</span><b>{{number(variable==='snow'?mapSnow?.sweMean:variable==='basin'?boot.spatial?.domainAreaKm2:mapFrame?.domainMean)}} <small>{{variable==='basin'?'km²':layers.find(l=>l.id===variable)?.unit}}</small></b></div><p class="screen-fine">{{variable==='snow'?'模型日末雪水当量，非遥感或地面积雪实测。':variable==='temperature'?'ERA5-Land气温基准，尚未作高程修正。':variable==='evaporation'?'公开蒸发能力，非实测湖面蒸发。':variable==='precipitation'?'ERA5-Land真实小时驱动，按北京时间累计24小时。':'气象格网与500 m高程带计算单元分别管理。'}}</p></section>
    <section class="screen-card river-card"><div class="screen-card-title"><h3>四河与湖周来水</h3><span>m³/s</span></div><button v-for="r in basinStats" :key="r.id" :class="['river-row',r.id,{on:feature?.id===r.id}]" @click="feature={kind:'basin',id:r.id,name:r.name,areaKm2:r.spatial?.areaKm2}"><span class="river-symbol" :class="r.id">●</span><span><b>{{r.name}}</b><small>{{number(r.spatial?.areaKm2,0)}} km²</small></span><strong>{{number(r.flow,1)}}</strong></button><div class="screen-card-footer">杜加为扎加内部断面，不重复计入总入湖流量。</div></section>
    <section class="screen-card screen-readiness"><div class="screen-card-title"><h3>业务状态</h3><span>STATUS</span></div><div><span>历史气象驱动</span><b :class="boot.annualValidation?.ready?'status-ready':'status-pending'">{{boot.annualValidation?.ready?'2023—2025完整':'尚待补齐'}}</b></div><div><span>实时遥测</span><b class="status-pending">未接入</b></div><div><span>7—15天预报</span><b class="status-pending">待接入</b></div><div><span>预警阈值</span><b class="status-pending">待业务核定</b></div><button @click="emit('navigate','model')">{{boot.annualValidation?.ready?'完整历史驱动已接入 · 查看资料 →':'查看资料 / 继续格网下载 →'}}</button></section>
   </aside>
   <div class="screen-center">
    <section class="screen-card screen-map-card"><div class="screen-card-title"><h3>流域湖情一张图</h3><span>{{loading?'读取资料…':mapLoading?'更新图层…':day+' · '+(mode==='model'?'模拟回放':'监测回放')}}</span></div><ScreenMap :stations="stations" :selected="stationId" :focus="feature?.kind==='basin'?feature.id:null" :frame="mapFrame" :snow="mapSnow" :variable="variable" :show-ice="show.ice" :show-rivers="show.rivers" :show-terrain="show.terrain" :show-stations="show.stations" :show-control="show.control" :show-names="show.names" @select="stationId=$event;feature=null" @feature="feature=$event" @failure="mapError=$event"/><div v-if="mapError" class="screen-map-notice" role="status">{{mapError}}</div><div v-if="feature" class="screen-feature"><div><strong>{{feature.name||feature.id}}</strong><span>{{feature.areaKm2?number(feature.areaKm2)+' km²':feature.kind==='glacier'?'冰川边界要素':'空间图层'}}</span></div><button @click="feature=null">收起 ×</button></div><div class="screen-map-footer"><span><i class="key-lake"></i>湖泊</span><span><i class="key-river"></i>河网</span><span><i class="key-ice"></i>冰川</span><span>可定位测站 {{stations.filter(s=>s.located).length}} / {{stations.length}}<small>四岸坐标待核验</small></span></div></section>
    <section class="screen-card screen-timeline"><div class="replay-top"><b>过程回放</b><button :disabled="!dates.length" @click="play">{{playing?'Ⅱ 暂停':'▷ 播放'}}</button><button :disabled="index<=0" @click="stop();move(-1)">前一天</button><button :disabled="index>=dates.length-1" @click="stop();move(1)">后一天</button><label>速度<select v-model.number="speed"><option :value="1">1×</option><option :value="2">2×</option><option :value="4">4×</option></select></label><input type="date" aria-label="大屏回放日期" :min="dates[0]" :max="dates.at(-1)" :value="day" @change="setDay($event.target.value)"></div><input type="range" aria-label="大屏时间轴" :min="0" :max="Math.max(0,dates.length-1)" :value="index" :disabled="!dates.length" @input="setDay(dates[Number($event.target.value)])"><div class="replay-ticks"><span>{{dates[0]||'—'}}</span><b>{{day||'暂无可回放资料'}} · {{dates.length?index+1:0}}/{{dates.length}}</b><span>{{dates.at(-1)||'—'}}</span></div></section>
   </div>
   <aside class="screen-right">
    <section class="screen-card lake-focus"><div class="screen-card-title"><h3>主站湖情</h3><span>OBSERVED</span></div><div class="latest-level"><span>最近可靠日水位</span><b>{{number(main?.latest?.value,3)}}<em>m</em></b><small>{{main?.latest?.date||'暂无资料'}} · 历史观测，非实时</small></div><div class="shore-values"><div v-for="s in stations.filter(s=>s.id.startsWith('SLC-'))" :key="s.id"><button @click="stationId=s.id;feature=null">{{s.name.replace('色林错','')}}</button><strong>{{number(exactValue(s,day),3)}}</strong></div></div><p class="screen-fine">四岸水位基准未统一，仅独立展示，不平均替代主站。</p></section>
    <section class="screen-card water-budget"><div class="screen-card-title"><h3>湖泊水量收支</h3><span>百万 m³ / d</span></div><div v-for="f in flux" :key="f.key" :class="['budget-row',f.key]"><span>{{f.label}}</span><div><i :style="{width:(f.value==null?0:Math.abs(f.value)/volumeScale*100)+'%'}"></i></div><b>{{f.value==null?'—':(f.sign<0?'−':f.value>0?'+':'')+number(f.value)}}</b></div><p class="screen-fine">{{current?.lakeActiveHours?`湖位有效演算 ${current.lakeActiveHours} 小时；未满24小时为窗口内累计。`:'所选日无有效湖位演算窗口，不展示虚构收支。'}}地下水净交换与外流暂按零。</p></section>
    <section class="screen-card station-focus"><div class="screen-card-title"><h3>测站详情</h3><button @click="openStation">资料 ↗</button></div><select v-model="stationId" aria-label="大屏选站"><option v-for="s in stations" :key="s.id" :value="s.id">{{s.name}}{{!s.located?' · 坐标待核验':''}}</option></select><div class="station-value"><b>{{number(selectedValue,selected?.variable==='level'?3:2)}}<small>{{selectedUnit}}</small></b><span>{{day}} · {{selectedValue==null?'该日缺测':'整编实测'}}</span></div><ScreenChart :rows="selectedRows" :series="[{key:'value',label:'实测'},...(mode==='model'&&['SLC','DUJA'].includes(stationId)?[{key:'sim',label:'模拟'}]:[])]" :unit="selectedUnit" :day="day" :dark="dark" @day="setDay"/></section>
   </aside>
  </div>
  <div class="screen-bottom-grid"><section class="screen-card"><div class="screen-card-title"><h3>湖位涨落过程</h3><span>m · 点击曲线定位日期</span></div><ScreenChart :rows="lakeRows" :series="mode==='model'?[{key:'lakeLevel',label:'模拟湖位',area:true},{key:'observedLevel',label:'主站实测'}]:[{key:'value',label:'主站实测'}]" unit="m" :day="day" :dark="dark" @day="setDay"/></section><section class="screen-card"><div class="screen-card-title"><h3>流域来水过程</h3><span>m³/s · 日均流量</span></div><ScreenChart :rows="flowRows" :series="mode==='model'?[{key:'total',label:'总入湖',area:true},{key:'duja',label:'杜加模拟'},{key:'observedFlow',label:'杜加实测'}]:[{key:'value',label:'杜加实测'}]" unit="m³/s" :day="day" :dark="dark" @day="setDay"/></section><section class="screen-card"><div class="screen-card-title"><h3>高寒过程诊断</h3><span>mm/d · 模型过程</span></div><ScreenChart :rows="result?.daily||[]" :series="[{key:'snowmeltMm',label:'融雪补给'},{key:'icemeltMm',label:'融冰补给'},{key:'etMm',label:'实际蒸散'}]" unit="mm/d" :zero="true" :day="day" :dark="dark" @day="setDay"/><span v-if="!result" class="screen-empty-caption">选择模型成果后查看冰雪过程</span></section></div>
  <div class="screen-footnote"><span>多源监测 <i>→</i> 冰雪新安江 <i>→</i> 四河入湖 <i>→</i> 湖泊平衡 <i>→</i> 湖位变化</span><span>历史资料与计算回放 · 预警等级待阈值核定 · v{{boot.version}}</span></div>
 </section>
</template>
